struct Vurio_Dedup_DuplicateGroupUpdate: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  var type: Vurio_Dedup_DuplicateGroupUpdate.UpdateType = .added

  var index: Int32 = 0

  var group: Vurio_Dedup_DuplicateGroup {
    get {_group ?? Vurio_Dedup_DuplicateGroup()}
    set {_group = newValue}
  }
  /// Returns true if `group` has been explicitly set.
  var hasGroup: Bool {self._group != nil}
  /// Clears the value of `group`. Subsequent reads from it will return its default value.
  mutating func clearGroup() {self._group = nil}

  var unknownFields = SwiftProtobuf.UnknownStorage()

  enum UpdateType: SwiftProtobuf.Enum, Swift.CaseIterable {
    typealias RawValue = Int
    case added // = 0
    case updated // = 1
    case deleted // = 2

    /// The finder re-clustered: groups may have been added, dropped, merged or
    /// re-ordered (a new representative changes a group's capture date, which
    /// is what the list sorts on). No per-row delta is meaningful, so the
    /// client re-fetches its loaded pages and re-anchors its scroll position.
    /// `index` and `group` are unset.
    case reload // = 3
    case UNRECOGNIZED(Int)

    init() {
      self = .added
    }

    init?(rawValue: Int) {
      switch rawValue {
      case 0: self = .added
      case 1: self = .updated
      case 2: self = .deleted
      case 3: self = .reload
      default: self = .UNRECOGNIZED(rawValue)
      }
    }

    var rawValue: Int {
      switch self {
      case .added: return 0
      case .updated: return 1
      case .deleted: return 2
      case .reload: return 3
      case .UNRECOGNIZED(let i): return i
      }
    }

    // The compiler won't synthesize support with the UNRECOGNIZED case.
    static let allCases: [Vurio_Dedup_DuplicateGroupUpdate.UpdateType] = [
      .added,
      .updated,
      .deleted,
      .reload,
    ]

  }

  init() {}

  fileprivate var _group: Vurio_Dedup_DuplicateGroup? = nil
}

